  // Inject Rate Limiting Headers
  res.setHeader('X-RateLimit-Limit', '100');
  res.setHeader('X-RateLimit-Remaining', '97');
  res.setHeader('X-RateLimit-Reset', Math.floor(Date.now() / 1000 + 60).toString());

  // Sane Defaults
  const page = Math.max(1, parseInt(req.query.page as string, 10) || 1);
  const limit = Math.min(50, Math.max(1, parseInt(req.query.limit as string, 10) || 10));
  const status = (req.query.status as string) || 'active';

  const { data, total } = await projectService.findPaginated({ page, limit, status });

  return res.status(200).json({
    data,
    meta: {
      pagination: {
        page,
        limit,
        totalItems: total,
        totalPages: Math.ceil(total / limit)
      }
    }
  });
};

