import Redis from 'ioredis';
const redis = new Redis(process.env.REDIS_URL || 'redis://localhost:6379');

// Cache-Aside Helper Function
export async function getCachedData<T>(key: string, ttlSeconds: number, fetchFn: () => Promise<T>): Promise<T> {
  const cached = await redis.get(key);
  if (cached) {
    return JSON.parse(cached) as T; // Cache HIT (~0.8ms)
  }
  const freshData = await fetchFn(); // Cache MISS -> Fetch from Database
  await redis.set(key, JSON.stringify(freshData), 'EX', ttlSeconds);
  return freshData;
}

// In-Memory Rate Limiting Middleware (50 req/min)
export const rateLimiter = async (req: Request, res: Response, next: NextFunction) => {
  const clientIp = req.headers['x-forwarded-for'] || req.ip || '127.0.0.1';
  const key = `ratelimit:${clientIp}`;
  const current = await redis.incr(key);
  if (current === 1) await redis.expire(key, 60);
  if (current > 50) {
    return res.status(429).json({ error: '429 Too Many Requests: Rate limit exceeded.' });
  }
  next();
};

