import { Request, Response, NextFunction } from 'express';
import Redis from 'ioredis';

const redis = new Redis(process.env.REDIS_URL || 'redis://localhost:6379');

// 1. Generic Cache-Aside Pattern
export async function getOrSetCache<T>(
  key: string,
  ttlSeconds: number,
  fetchDb: () => Promise<T>
): Promise<T> {
  const cached = await redis.get(key);
  if (cached) {
    return JSON.parse(cached);
  }

  const freshData = await fetchDb();
  await redis.set(key, JSON.stringify(freshData), 'EX', ttlSeconds);
  return freshData;
}

// 2. High-Speed Rate Limiting Middleware (HTTP 429)
export async function rateLimitGuard(req: Request, res: Response, next: NextFunction) {
  const ip = req.ip || '127.0.0.1';
  const key = `rate:${ip}`;

  const requests = await redis.incr(key);
  if (requests === 1) {
    await redis.expire(key, 60); // 1-minute sliding window
  }

  res.setHeader('X-RateLimit-Limit', '50');
  res.setHeader('X-RateLimit-Remaining', Math.max(0, 50 - requests).toString());

  if (requests > 50) {
    return res.status(429).json({
      error: 'HTTP 429 Too Many Requests',
      message: 'Rate limit exceeded. Please wait 60 seconds.'
    });
  }
  next();
}

