var rdb = redis.NewClient(&redis.Options{
    Addr: "localhost:6379",
})

// Cache-Aside Helper in Go
func GetCachedProduct(ctx context.Context, id string) (*Product, error) {
    key := "product:" + id
    val, err := rdb.Get(ctx, key).Result()
    if err == nil {
        var p Product
        json.Unmarshal([]byte(val), &p)
        return &p, nil // Cache Hit
    }

    // Cache Miss -> Query Database
    p, err := dbQueryProduct(id)
    if err != nil {
        return nil, err
    }

    bytes, _ := json.Marshal(p)
    rdb.Set(ctx, key, bytes, time.Hour) // Set TTL = 1 hour
    return p, nil
}

// Rate Limiting Middleware (50 req/min)
func RateLimitMiddleware(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        ctx := r.Context()
        key := "ratelimit:" + r.RemoteAddr
        count, _ := rdb.Incr(ctx, key).Result()
        if count == 1 {
            rdb.Expire(ctx, key, time.Minute)
        }
        if count > 50 {
            http.Error(w, "429 Too Many Requests", http.StatusTooManyRequests)
            return
        }
        next.ServeHTTP(w, r)
    })
}

