#[derive(Serialize, Deserialize)]
pub struct Product {
    pub id: String,
    pub name: String,
    pub price: f64,
}

pub async fn get_product(
    product_id: String,
    mut con: redis::aio::ConnectionManager,
) -> Result<Json<Product>, StatusCode> {
    let cache_key = format!("product:{}", product_id);

    // 1. Check Redis Cache
    let cached: Option<String> = con.get(&cache_key).await.unwrap_or(None);
    if let Some(json_str) = cached {
        if let Ok(p) = serde_json::from_str::<Product>(&json_str) {
            return Ok(Json(p)); // Cache HIT
        }
    }

    // 2. Cache MISS -> Fetch from PostgreSQL
    let product = db_fetch_product(&product_id).await.map_err(|_| StatusCode::NOT_FOUND)?;
    let serialized = serde_json::to_string(&product).unwrap();
    let _: () = con.set_ex(&cache_key, serialized, 3600).await.unwrap_or(());

    Ok(Json(product))
}
